import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Kakito.html","title":"Kakito","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.38,"words":115},"filePathRelative":"Kakito.md"}`),a={name:`Kakito.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="kakito" tabindex="-1"><a class="header-anchor" href="#kakito"><span>Kakito</span></a></h1><ul><li><a href="https://github.com/Karino2DIYApp/Kakito" target="_blank" rel="noopener noreferrer">Karino2DIYApp/Kakito: BOOX用漢字書き取りアプリ</a></li></ul><p><a href="./BOOX.html">BOOX</a>用の漢字書き取りアプリ。<a href="./Karino2DIYApp.html">Karino2DIYApp</a></p><h2 id="フォント選定" tabindex="-1"><a class="header-anchor" href="#フォント選定"><span>フォント選定</span></a></h2><p>教科書体のいいフォントを探しているが、フリーだとなかなか無い。</p><ul><li><a href="https://kaku-navi.com/kanji/kanji15056.html" target="_blank" rel="noopener noreferrer">「裏」の書き順(画数)｜正しい漢字の書き方【かくなび】</a> このサイトで書き順を調べる</li><li><a href="https://kakijun.jp/page/1345200.html" target="_blank" rel="noopener noreferrer">「愚」の書き方 - 漢字の正しい書き順(筆順)</a> こちらも使う</li></ul><h3 id="yuji-syuku" tabindex="-1"><a class="header-anchor" href="#yuji-syuku"><span>Yuji Syuku</span></a></h3><ul><li><a href="https://fonts.google.com/specimen/Yuji+Syuku" target="_blank" rel="noopener noreferrer">Yuji Syuku - Google Fonts</a></li></ul><p>毛筆っぽいフォントで少し太すぎて見づらい事もあるが、正しい漢字としてはフリーフォントの中では一番納得感はあるか。ちょっと達筆過ぎる感じはあるが。</p><h3 id="kleeone" tabindex="-1"><a class="header-anchor" href="#kleeone"><span>KleeOne</span></a></h3><ul><li><a href="https://fonts.google.com/specimen/Klee+One" target="_blank" rel="noopener noreferrer">Klee One - Google Fonts</a></li></ul><p>裏のハネが二画になるのがいまいちだが、他は良い。</p><h3 id="zen-kurenaido" tabindex="-1"><a class="header-anchor" href="#zen-kurenaido"><span>Zen Kurenaido</span></a></h3><ul><li><a href="https://fonts.google.com/specimen/Zen+Kurenaido" target="_blank" rel="noopener noreferrer">Zen Kurenaido - Google Fonts</a></li></ul><p>愚かが真ん中が直線じゃない。嬉しいが突き抜ける。 ただ裏は綺麗なハネ。</p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};